import 'package:flutter/material.dart';
import 'package:platform_core_frontend/features/finance/presentation/widgets/finance_labels.dart';
import 'package:platform_core_frontend/shared/utils/date_format_utils.dart';
import 'package:platform_core_frontend/shared/widgets/app_card.dart';
class ContributionTransactionCard extends StatelessWidget{const ContributionTransactionCard({super.key,required this.title,this.subtitle,required this.amount,required this.paymentMode,this.paidAt,required this.collectedByName,this.note});final String title,paymentMode,collectedByName;final String? subtitle,note;final double amount;final DateTime? paidAt;@override Widget build(BuildContext context)=>AppCard(margin:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold))),Text(formatRupees(amount),style:const TextStyle(fontWeight:FontWeight.bold))]),if(subtitle?.isNotEmpty==true)Text(subtitle!),Text('$paymentMode • ${formatReadableDate(paidAt,nullText:'Not available')}'),Text('Collected by $collectedByName'),if(note!=null)Text(note!)]));}
